fn input(b:&Binding,at:u32,cell:WorldCell,center:WorldCell)->movement::input::Inputs{movement::input::Inputs{at:Some(at),event:Some(512),flags:Some(1),point:Some(point(cell,center)),hud_intercept_absent:Some(true),viewport_bounds_passed:Some(true),plain64b8f6:Some(false),runtime:runtime(b)}}
